--
-- Structure de la table `projects`
--

CREATE TABLE `projects` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `budget` decimal(10,2) DEFAULT NULL,
  `employer_id` int(11) NOT NULL,
  `status` enum('open','in progress','cancelled','completed') DEFAULT 'open',
  `deadline` datetime DEFAULT NULL,
  `address` text DEFAULT NULL,
  `current_progress` int(11) DEFAULT 0,
  `project_type` enum('solo','team') DEFAULT 'solo',
  `cancellation_reason` text DEFAULT NULL,
  `completion_date` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `client_id` int(11) NOT NULL,
  `main_tasks_number` int(11) NOT NULL,
  `current_phase` int(11) DEFAULT 1,
  `deposit_paid` tinyint(1) DEFAULT 0,
  `final_payment_paid` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

