--
-- Structure de la table `project_views`
--

CREATE TABLE `project_views` (
  `id` int(11) NOT NULL,
  `worker_id` int(11) NOT NULL,
  `project_id` int(11) NOT NULL,
  `viewed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `view_duration` int(11) DEFAULT NULL COMMENT 'Duration in seconds',
  `location_match` tinyint(1) DEFAULT 0 COMMENT '1 if project location matches worker location',
  `budget_match` tinyint(1) DEFAULT 0 COMMENT '1 if project budget is within worker preferred range',
  `job_match` tinyint(1) DEFAULT 0 COMMENT '1 if project requires worker job categories',
  `is_clicked` tinyint(1) DEFAULT 0 COMMENT '1 if worker clicked to view project details',
  `is_applied` tinyint(1) DEFAULT 0 COMMENT '1 if worker applied to this project',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_detail_view` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

